// Doubly Linked List from scratch
#include <iostream>
using namespace std;

struct DNode {
    int data;
    DNode* prev;
    DNode* next;
    DNode(int val) : data(val), prev(nullptr), next(nullptr) {}
};

class DoublyLinkedList {
    DNode* head;
    DNode* tail;

public:
    DoublyLinkedList() : head(nullptr), tail(nullptr) {}

    void append(int val) {
        DNode* n = new DNode(val);
        if (!head) {
            head = tail = n;
        } else {
            tail->next = n;
            n->prev = tail;
            tail = n;
        }
    }

    void prepend(int val) {
        DNode* n = new DNode(val);
        if (!head) {
            head = tail = n;
        } else {
            n->next = head;
            head->prev = n;
            head = n;
        }
    }

    void deleteNode(DNode* target) {
        if (!target) return;
        if (target == head) head = head->next;
        if (target == tail) tail = tail->prev;
        if (target->prev) target->prev->next = target->next;
        if (target->next) target->next->prev = target->prev;
        delete target;
    }

    void displayForward() {
        cout << "Forward:  ";
        DNode* curr = head;
        while (curr) {
            cout << curr->data << " <-> ";
            curr = curr->next;
        }
        cout << "nullptr\n";
    }

    void displayBackward() {
        cout << "Backward: ";
        DNode* curr = tail;
        while (curr) {
            cout << curr->data << " <-> ";
            curr = curr->prev;
        }
        cout << "nullptr\n";
    }

    ~DoublyLinkedList() {
        while (head) {
            DNode* temp = head;
            head = head->next;
            delete temp;
        }
    }
};

int main() {
    DoublyLinkedList list;

    list.append(10);
    list.append(20);
    list.append(30);
    list.displayForward();
    list.displayBackward();

    list.prepend(5);
    cout << "\nAfter prepend(5):\n";
    list.displayForward();

    return 0;
}

// Circular Linked List (singly) - Round Robin demo
#include <iostream>
using namespace std;

struct CNode {
    int data;
    CNode* next;
    CNode(int v) : data(v), next(nullptr) {}
};

class CircularList {
    CNode* tail;  // tail->next is head

public:
    CircularList() : tail(nullptr) {}

    void append(int val) {
        CNode* n = new CNode(val);
        if (!tail) {
            n->next = n;
            tail = n;
        } else {
            n->next = tail->next;
            tail->next = n;
            tail = n;
        }
    }

    void display() {
        if (!tail) return;
        CNode* curr = tail->next;
        do {
            cout << curr->data << " -> ";
            curr = curr->next;
        } while (curr != tail->next);
        cout << "(back to start)\n";
    }

    // Simulate round-robin: rotate the list
    void rotate() {
        if (tail) tail = tail->next;
    }

    int getCurrent() {
        return tail ? tail->next->data : -1;
    }

    ~CircularList() {
        if (!tail) return;
        CNode* curr = tail->next;
        tail->next = nullptr;
        while (curr) {
            CNode* temp = curr;
            curr = curr->next;
            delete temp;
        }
    }
};

int main() {
    CircularList players;
    players.append(1);
    players.append(2);
    players.append(3);
    players.append(4);

    cout << "Players in circle: ";
    players.display();

    cout << "\nRound-robin turns:\n";
    for (int i = 0; i < 6; i++) {
        cout << "Turn " << i+1 << ": Player " << players.getCurrent() << "\n";
        players.rotate();
    }

    return 0;
}

// Binary Tree: creation and traversals
#include <iostream>
#include <queue>
using namespace std;

struct TreeNode {
    int data;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int val) : data(val), left(nullptr), right(nullptr) {}
};

// Depth-First Traversals
void inorder(TreeNode* root) {
    if (!root) return;
    inorder(root->left);
    cout << root->data << " ";
    inorder(root->right);
}

void preorder(TreeNode* root) {
    if (!root) return;
    cout << root->data << " ";
    preorder(root->left);
    preorder(root->right);
}

void postorder(TreeNode* root) {
    if (!root) return;
    postorder(root->left);
    postorder(root->right);
    cout << root->data << " ";
}

// Breadth-First (Level Order)
void levelOrder(TreeNode* root) {
    if (!root) return;
    queue<TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
        TreeNode* curr = q.front(); q.pop();
        cout << curr->data << " ";
        if (curr->left) q.push(curr->left);
        if (curr->right) q.push(curr->right);
    }
}

int height(TreeNode* root) {
    if (!root) return -1;
    return 1 + max(height(root->left), height(root->right));
}

int countNodes(TreeNode* root) {
    if (!root) return 0;
    return 1 + countNodes(root->left) + countNodes(root->right);
}

int main() {
    /*
            1
           / \
          2   3
         / \   \
        4   5   6
    */
    TreeNode* root = new TreeNode(1);
