// Tree properties and mirror operation
#include <iostream>
using namespace std;

struct TreeNode {
    int data;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int v) : data(v), left(nullptr), right(nullptr) {}
};

// Mirror: swap left and right subtrees recursively
void mirror(TreeNode* root) {
    if (!root) return;
    swap(root->left, root->right);
    mirror(root->left);
    mirror(root->right);
}

void inorder(TreeNode* root) {
    if (!root) return;
    inorder(root->left);
    cout << root->data << " ";
    inorder(root->right);
}

int main() {
    TreeNode* root = new TreeNode(1);
    root->left = new TreeNode(2);
    root->right = new TreeNode(3);
    root->left->left = new TreeNode(4);
    root->left->right = new TreeNode(5);

    cout << "Original inorder: ";
    inorder(root);
    cout << "\n";

    mirror(root);

    cout << "Mirrored inorder: ";
    inorder(root);
    cout << "\n";

    return 0;
}

// Binary Search Tree: search, insert, inorder traversal
#include <iostream>
using namespace std;

struct TreeNode {
    int data;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int v) : data(v), left(nullptr), right(nullptr) {}
};

class BST {
    TreeNode* root;

    TreeNode* insertHelper(TreeNode* node, int val) {
        if (!node) return new TreeNode(val);
        if (val < node->data)
            node->left = insertHelper(node->left, val);
        else if (val > node->data)
            node->right = insertHelper(node->right, val);
        return node;
    }

    bool searchHelper(TreeNode* node, int val) {
        if (!node) return false;
        if (node->data == val) return true;
        if (val < node->data)
            return searchHelper(node->left, val);
        return searchHelper(node->right, val);
    }

    void inorderHelper(TreeNode* node) {
        if (!node) return;
        inorderHelper(node->left);
        cout << node->data << " ";
        inorderHelper(node->right);
    }

    TreeNode* findMin(TreeNode* node) {
        while (node && node->left)
            node = node->left;
        return node;
    }

    TreeNode* deleteHelper(TreeNode* node, int val) {
        if (!node) return nullptr;
        if (val < node->data)
            node->left = deleteHelper(node->left, val);
        else if (val > node->data)
            node->right = deleteHelper(node->right, val);
        else {
            // Node found
            if (!node->left) {
                TreeNode* temp = node->right;
                delete node;
                return temp;
            }
            if (!node->right) {
                TreeNode* temp = node->left;
                delete node;
                return temp;
            }
            // Two children: replace with inorder successor
            TreeNode* succ = findMin(node->right);
            node->data = succ->data;
            node->right = deleteHelper(node->right, succ->data);
        }
        return node;
    }

public:
    BST() : root(nullptr) {}

    void insert(int val) { root = insertHelper(root, val); }
    bool search(int val) { return searchHelper(root, val); }
    void remove(int val) { root = deleteHelper(root, val); }

    void inorder() {
        inorderHelper(root);
        cout << "\n";
    }
};

int main() {
    BST tree;
    int values[] = {50, 30, 70, 20, 40, 60, 80};
    for (int v : values) tree.insert(v);

    cout << "Inorder (sorted): ";
