// BST vs sorted array: search comparison
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

struct TreeNode {
    int data; TreeNode* left; TreeNode* right;
    TreeNode(int v) : data(v), left(nullptr), right(nullptr) {}
};

TreeNode* insert(TreeNode* root, int val) {
    if (!root) return new TreeNode(val);
    if (val < root->data) root->left = insert(root->left, val);
    else root->right = insert(root->right, val);
    return root;
}

bool bstSearch(TreeNode* root, int val, int& comparisons) {
    comparisons++;
    if (!root) return false;
    if (root->data == val) return true;
    if (val < root->data) return bstSearch(root->left, val, comparisons);
    return bstSearch(root->right, val, comparisons);
}

int linearSearch(const vector<int>& arr, int val, int& comparisons) {
    for (int i = 0; i < (int)arr.size(); i++) {
        comparisons++;
        if (arr[i] == val) return i;
    }
    return -1;
}

int main() {
    // Build BST and sorted array with same data
    TreeNode* root = nullptr;
    vector<int> arr;
    for (int i = 1; i <= 1000; i += 2) {
        root = insert(root, i);
        arr.push_back(i);
    }

    int target = 999;
    int bstComp = 0, linComp = 0;

    bstSearch(root, target, bstComp);
    linearSearch(arr, target, linComp);

    cout << "BST search comparisons:    " << bstComp << "\n";
    cout << "Linear search comparisons: " << linComp << "\n";
    cout << "BST is roughly O(log n), linear is O(n)\n";

    return 0;
}

// Hash Table with separate chaining (from scratch)
#include <iostream>
#include <string>
using namespace std;

#define TABLE_SIZE 16

struct HashNode {
    string key;
    int value;
    HashNode* next;
    HashNode(string k, int v) : key(k), value(v), next(nullptr) {}
};

class HashTable {
    HashNode* buckets[TABLE_SIZE];

    unsigned long hashFunc(const string& str) {
        unsigned long hash = 5381;
        for (char c : str)
            hash = ((hash << 5) + hash) + c;
        return hash % TABLE_SIZE;
    }

public:
    HashTable() {
        for (int i = 0; i < TABLE_SIZE; i++)
            buckets[i] = nullptr;
    }

    void insert(const string& key, int value) {
        int idx = hashFunc(key);
        HashNode* curr = buckets[idx];
        while (curr) {
            if (curr->key == key) {
                curr->value = value;  // Update existing
                return;
            }
            curr = curr->next;
        }
        HashNode* n = new HashNode(key, value);
        n->next = buckets[idx];
        buckets[idx] = n;
    }

    int* get(const string& key) {
        int idx = hashFunc(key);
        HashNode* curr = buckets[idx];
        while (curr) {
            if (curr->key == key)
                return &curr->value;
            curr = curr->next;
        }
        return nullptr;
    }

    void remove(const string& key) {
        int idx = hashFunc(key);
        HashNode* curr = buckets[idx];
        HashNode* prev = nullptr;
        while (curr) {
            if (curr->key == key) {
                if (prev) prev->next = curr->next;
                else buckets[idx] = curr->next;
                delete curr;
                return;
            }
            prev = curr;
            curr = curr->next;
        }
    }

    void display() {
        for (int i = 0; i < TABLE_SIZE; i++) {
            if (buckets[i]) {
                cout << "Bucket " << i << ": ";
                HashNode* curr = buckets[i];
                while (curr) {
                    cout << "[" << curr->key << ":" << curr->value << "] -> ";
                    curr = curr->next;
                }
                cout << "nullptr\n";
            }
        }
    }

    ~HashTable() {
        for (int i = 0; i < TABLE_SIZE; i++) {
            while (buckets[i]) {
                HashNode* temp = buckets[i];
                buckets[i] = buckets[i]->next;
                delete temp;
            }
        }
    }
};

int main() {
    HashTable ht;
    ht.insert("apple", 100);
    ht.insert("banana", 200);
    ht.insert("cherry", 300);
    ht.insert("date", 400);

    cout << "Hash table contents:\n";
    ht.display();

    int* val = ht.get("banana");
    if (val)
        cout << "\nbanana -> " << *val << "\n";

    ht.remove("banana");
    cout << "\nAfter removing 'banana':\n";
    ht.display();

    return 0;
}

