// Linear Search vs Binary Search comparison
#include <iostream>
#include <vector>
#include <algorithm>
#include <chrono>
using namespace std;

int linearSearch(const vector<int>& arr, int target) {
    for (int i = 0; i < (int)arr.size(); i++)
        if (arr[i] == target) return i;
    return -1;
}

int binarySearch(const vector<int>& arr, int target) {
    int left = 0, right = arr.size() - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == target) return mid;
        if (arr[mid] < target) left = mid + 1;
        else right = mid - 1;
    }
    return -1;
}

int main() {
    const int N = 10000000;  // 10 million elements
    vector<int> arr(N);
    for (int i = 0; i < N; i++) arr[i] = i;

    int target = N - 1;  // Worst case for linear search

    auto t1 = chrono::high_resolution_clock::now();
    int idx1 = linearSearch(arr, target);
    auto t2 = chrono::high_resolution_clock::now();

    auto t3 = chrono::high_resolution_clock::now();
    int idx2 = binarySearch(arr, target);
    auto t4 = chrono::high_resolution_clock::now();

    auto dt_lin = chrono::duration_cast<chrono::microseconds>(t2 - t1).count();
    auto dt_bin = chrono::duration_cast<chrono::microseconds>(t4 - t3).count();

    cout << "Array size: " << N << "\n";
    cout << "Linear search: " << dt_lin << " us (found at " << idx1 << ")\n";
    cout << "Binary search: " << dt_bin << " us (found at " << idx2 << ")\n";
    cout << "Speedup: " << (double)dt_lin / dt_bin << "x\n";

    return 0;
}

// Finding first and last occurrence using binary search
#include <iostream>
#include <vector>
using namespace std;

int findFirst(const vector<int>& arr, int target) {
    int left = 0, right = arr.size() - 1;
    int result = -1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == target) {
            result = mid;
            right = mid - 1;  // Keep searching left
        } else if (arr[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return result;
}

int findLast(const vector<int>& arr, int target) {
    int left = 0, right = arr.size() - 1;
    int result = -1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == target) {
            result = mid;
            left = mid + 1;  // Keep searching right
        } else if (arr[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return result;
}

int main() {
    vector<int> arr = {1, 2, 4, 4, 4, 5, 6, 7};

    cout << "Array: ";
    for (int x : arr) cout << x << " ";
    cout << "\n\n";

    int target = 4;
    int first = findFirst(arr, target);
    int last = findLast(arr, target);

    cout << "First occurrence of " << target << ": index " << first << "\n";
    cout << "Last occurrence of " << target << ": index " << last << "\n";
    cout << "Total occurrences: " << (last - first + 1) << "\n";

    return 0;
}

// Min-Heap implementation from scratch
#include <iostream>
#include <vector>
#include <stdexcept>
using namespace std;

class MinHeap {
    vector<int> heap;

    int parent(int i) { return (i - 1) / 2; }
    int leftChild(int i) { return 2 * i + 1; }
    int rightChild(int i) { return 2 * i + 2; }

    void heapifyUp(int i) {
        while (i > 0 && heap[parent(i)] > heap[i]) {
            swap(heap[parent(i)], heap[i]);
            i = parent(i);
        }
    }

    void heapifyDown(int i) {
        int minIdx = i;
        int l = leftChild(i);
        int r = rightChild(i);

        if (l < (int)heap.size() && heap[l] < heap[minIdx])
            minIdx = l;
        if (r < (int)heap.size() && heap[r] < heap[minIdx])
            minIdx = r;

        if (i != minIdx) {
            swap(heap[i], heap[minIdx]);
            heapifyDown(minIdx);
        }
    }

public:
    void insert(int val) {
        heap.push_back(val);
        heapifyUp(heap.size() - 1);
    }

    int extractMin() {
        if (heap.empty())
            throw runtime_error("Heap is empty");

        int minVal = heap[0];
        heap[0] = heap.back();
        heap.pop_back();
        if (!heap.empty())
            heapifyDown(0);
        return minVal;
    }

    int getMin() {
        if (heap.empty())
            throw runtime_error("Heap is empty");
        return heap[0];
    }

    bool isEmpty() { return heap.empty(); }
    int size() { return heap.size(); }

    void display() {
        cout << "Heap array: ";
        for (int x : heap) cout << x << " ";
        cout << "\n";
    }
};

int main() {
    MinHeap h;

    h.insert(50);
    h.insert(30);
    h.insert(20);
    h.insert(15);
    h.insert(10);
    h.insert(8);

    cout << "After insertions:\n";
    h.display();
    cout << "Minimum: " << h.getMin() << "\n\n";

    cout << "Extracting elements in order:\n";
    while (!h.isEmpty()) {
        cout << h.extractMin() << " ";
    }
    cout << "\n";

    return 0;
}

// Priority Queue applications: Top K elements and task scheduling
#include <iostream>
#include <queue>
#include <vector>
#include <functional>
