}

// Graph with adjacency list: BFS and DFS
#include <iostream>
#include <vector>
#include <queue>
#include <stack>
using namespace std;

class Graph {
    int V;
    vector<vector<int>> adj;

public:
    Graph(int vertices) : V(vertices) {
        adj.resize(V);
    }

    void addEdge(int u, int v) {
        adj[u].push_back(v);
        adj[v].push_back(u);  // Undirected graph
    }

    void bfs(int start) {
        vector<bool> visited(V, false);
        queue<int> q;

        visited[start] = true;
        q.push(start);

        cout << "BFS from " << start << ": ";
        while (!q.empty()) {
            int u = q.front(); q.pop();
            cout << u << " ";

            for (int v : adj[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    q.push(v);
                }
            }
        }
        cout << "\n";
    }

    void dfs(int start) {
        vector<bool> visited(V, false);
        stack<int> s;

        s.push(start);
        cout << "DFS from " << start << ": ";

        while (!s.empty()) {
            int u = s.top(); s.pop();
            if (visited[u]) continue;

            visited[u] = true;
            cout << u << " ";

            for (auto it = adj[u].rbegin(); it != adj[u].rend(); ++it) {
                if (!visited[*it])
                    s.push(*it);
            }
        }
        cout << "\n";
    }

    void display() {
        cout << "\nAdjacency List:\n";
        for (int i = 0; i < V; i++) {
            cout << i << ": ";
            for (int v : adj[i])
                cout << v << " ";
            cout << "\n";
        }
    }
};

