}

// Detect cycle in undirected graph using DFS
#include <iostream>
#include <vector>
using namespace std;

class Graph {
    int V;
    vector<vector<int>> adj;

    bool dfsCycle(int u, vector<bool>& visited, int parent) {
        visited[u] = true;
        for (int v : adj[u]) {
            if (!visited[v]) {
                if (dfsCycle(v, visited, u))
                    return true;
            } else if (v != parent) {
                return true;  // Found a back edge
            }
        }
        return false;
    }

public:
    Graph(int v) : V(v) { adj.resize(V); }
    void addEdge(int u, int v) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    bool hasCycle() {
        vector<bool> visited(V, false);
        for (int i = 0; i < V; i++)
            if (!visited[i])
                if (dfsCycle(i, visited, -1))
                    return true;
        return false;
    }
};

int main() {
    Graph g1(5);
    g1.addEdge(0, 1);
    g1.addEdge(1, 2);
    g1.addEdge(2, 3);
    g1.addEdge(3, 4);
    cout << "Graph 1 (no cycle): "
         << (g1.hasCycle() ? "Has cycle" : "No cycle") << "\n";

    Graph g2(5);
    g2.addEdge(0, 1);
    g2.addEdge(1, 2);
    g2.addEdge(2, 0);  // Creates cycle 0-1-2-0
    g2.addEdge(2, 3);
    g2.addEdge(3, 4);
    cout << "Graph 2 (has cycle): "
         << (g2.hasCycle() ? "Has cycle" : "No cycle") << "\n";

    return 0;
}

// Classic recursive algorithms
#include <iostream>
#include <vector>
using namespace std;

// Factorial
long long factorial(int n) {
    if (n <= 1) return 1;
    return n * factorial(n - 1);
}

// Fibonacci with memoization
long long fib(int n, vector<long long>& memo) {
    if (n <= 1) return n;
    if (memo[n] != -1) return memo[n];
    memo[n] = fib(n - 1, memo) + fib(n - 2, memo);
    return memo[n];
}

// Tower of Hanoi
void hanoi(int n, char from, char to, char aux) {
    if (n == 0) return;
    hanoi(n - 1, from, aux, to);
    cout << "Move disk " << n << " from " << from << " to " << to << "\n";
    hanoi(n - 1, aux, to, from);
}

// Generate all subsets (backtracking)
void subsets(const vector<int>& nums, vector<int>& current,
             int index, vector<vector<int>>& result) {
    if (index == (int)nums.size()) {
        result.push_back(current);
        return;
    }
    // Exclude current element
    subsets(nums, current, index + 1, result);
    // Include current element
    current.push_back(nums[index]);
    subsets(nums, current, index + 1, result);
    current.pop_back();  // Backtrack
}

int main() {
    cout << "5! = " << factorial(5) << "\n\n";

    vector<long long> memo(41, -1);
    cout << "fib(40) = " << fib(40, memo) << "\n\n";

