    return false;
}

void printBoard(const vector<int>& board, int n) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++)
            cout << (board[i] == j ? "Q " : ". ");
        cout << "\n";
    }
}

int main() {
    int n = 4;
    vector<int> board(n, -1);

    cout << "Solving " << n << "-Queens...\n";
    if (solveNQueens(board, 0, n)) {
        cout << "\nSolution:\n";
        printBoard(board, n);
    } else {
        cout << "No solution exists\n";
    }

    return 0;
}

// Demonstrating growth rates with timing
#include <iostream>
#include <vector>
#include <chrono>
using namespace std;

// O(1) - constant time
int getFirst(const vector<int>& arr) {
    return arr[0];
}

// O(n) - linear time
int sumArray(const vector<int>& arr) {
    int sum = 0;
    for (int x : arr) sum += x;
    return sum;
}

// O(n^2) - quadratic time
void printPairs(const vector<int>& arr) {
    int count = 0;
    for (size_t i = 0; i < arr.size(); i++)
        for (size_t j = i + 1; j < arr.size(); j++)
            count++;
    // cout << "Pairs: " << count << "\n";
}

int main() {
    vector<int> sizes = {1000, 5000, 10000};

    cout << "=== Time Complexity Demonstration ===\n\n";

    for (int n : sizes) {
        vector<int> arr(n);
        for (int i = 0; i < n; i++) arr[i] = i;

        // O(1)
        auto t1 = chrono::high_resolution_clock::now();
        getFirst(arr);
        auto t2 = chrono::high_resolution_clock::now();

        // O(n)
        auto t3 = chrono::high_resolution_clock::now();
        sumArray(arr);
        auto t4 = chrono::high_resolution_clock::now();

        // O(n^2)
        auto t5 = chrono::high_resolution_clock::now();
        printPairs(arr);
        auto t6 = chrono::high_resolution_clock::now();

        auto dt1 = chrono::duration_cast<chrono::nanoseconds>(t2 - t1).count();
        auto dt2 = chrono::duration_cast<chrono::microseconds>(t4 - t3).count();
        auto dt3 = chrono::duration_cast<chrono::milliseconds>(t6 - t5).count();

        cout << "n = " << n << ":\n";
        cout << "  O(1):   " << dt1 << " ns\n";
        cout << "  O(n):   " << dt2 << " us\n";
        cout << "  O(n^2): " << dt3 << " ms\n\n";
    }

    return 0;
}

